import collections, hashlib, json, math, re, time, xml.etree.ElementTree as ET
from pathlib import Path
root=Path('flavor-studio')
out=root/'qa/svg-path-audit.json'
out.parent.mkdir(parents=True,exist_ok=True)
manifest=json.loads((root/'assets/manifest.json').read_text())
meta={a['id']:a for a in manifest['assets']}
arity={'M':2,'L':2,'H':1,'V':1,'C':6,'S':4,'Q':4,'T':2,'A':7,'Z':0}
command_re=re.compile(r'[MmLlHhVvCcSsQqTtAaZz]')
number_re=re.compile(r'[+-]?(?:(?:[0-9]+\.[0-9]*)|(?:\.[0-9]+)|(?:[0-9]+))(?:[eE][+-]?[0-9]+)?')
def validate(d):
    errors=[];warnings=[]
    commands=list(command_re.finditer(d))
    if not commands:
        return [{'type':'no_command','detail':'Nonempty path contains no SVG command'}],[]
    if d[:commands[0].start()].strip():
        errors.append({'type':'invalid_prefix','detail':d[:commands[0].start()]})
    if commands[0].group().upper()!='M':
        errors.append({'type':'missing_initial_moveto','command':commands[0].group()})
    if re.search(r'(?i)nan|infinity|\binf\b',d):
        errors.append({'type':'nonfinite_literal'})
    if re.search(r'[0-9]+\.[0-9]+\.[0-9]+',d):
        warnings.append({'type':'adjacent_decimal_tokens','detail':'SVG can permit adjacent decimal tokens, but this may indicate a missing generator separator.'})
    for cidx,match in enumerate(commands):
        cmd=match.group();upper=cmd.upper();end=commands[cidx+1].start() if cidx+1<len(commands) else len(d)
        chunk=d[match.end():end];pos=0;values=[];error=False
        if upper=='Z':
            if chunk.strip():errors.append({'type':'closepath_has_parameters','command':cmd,'detail':chunk})
            continue
        while pos<len(chunk):
            start=pos
            while pos<len(chunk) and chunk[pos] in ' \t\r\n':pos+=1
            if pos<len(chunk) and chunk[pos]==',':
                if not values:errors.append({'type':'leading_comma','command':cmd,'offset':match.end()+pos})
                pos+=1
                while pos<len(chunk) and chunk[pos] in ' \t\r\n':pos+=1
                if pos==len(chunk) or chunk[pos]==',':
                    errors.append({'type':'invalid_comma','command':cmd,'offset':match.end()+pos});error=True;break
            if pos==len(chunk):break
            param_index=len(values)%arity[upper]
            if upper=='A' and param_index in (3,4):
                if chunk[pos] not in '01':
                    errors.append({'type':'invalid_arc_flag','command':cmd,'offset':match.end()+pos,'detail':chunk[pos:pos+15]});error=True;break
                token=chunk[pos];pos+=1
            else:
                num=number_re.match(chunk,pos)
                if not num:
                    errors.append({'type':'invalid_number_token','command':cmd,'offset':match.end()+pos,'detail':chunk[pos:pos+25]});error=True;break
                token=num.group();pos=num.end()
            val=float(token);values.append(val)
            if not math.isfinite(val):errors.append({'type':'nonfinite_number','command':cmd,'token':token})
            elif abs(val)>1920:warnings.append({'type':'large_coordinate','command':cmd,'token':token,'detail':'Magnitude exceeds 4x the 480px viewBox; inspect possible concatenated numbers.'})
            if upper=='A' and param_index in (0,1) and val<0:
                errors.append({'type':'negative_arc_radius','command':cmd,'token':token})
        if not values or len(values)%arity[upper]:
            errors.append({'type':'incorrect_parameter_count','command':cmd,'expectedMultiple':arity[upper],'actual':len(values),'detail':chunk.strip()})
    return errors,warnings
# Independent parser checks: implicit repetitions and adjacent signed/fractional
# numbers are legal; arc flags are parsed individually even when packed.
self_cases=[
 ('M0 0L1 2Z',True),('M0 0 1 2 3 4',True),('m.6.5l-1-2',True),
 ('M0 0A10 20 0 0110 20Z',True),('M0 0 Q1 2 3 4',True),
 ('M0 0 C1 2 3 4 5 6 S7 8 9 10 T11 12 H13 V14',True),
 ('M0 -11 Q7.6999999999999990 0 11 Q-7.6999999999999990 0 -11Z',False),
 ('M0 0 Q1 2 3',False),('M0 0L1e999 2',False),('M0 0A10 10 0 2 1 3 4',False),
 ('M0 0Z 1',False),('L1 2',False),('M0 0L1,,2',False),('M0 0 LNaN 2',False)
]
for value,expected in self_cases:
    assert (not validate(value)[0])==expected,(value,validate(value))
files=sorted((root/'assets/ingredients').glob('*.svg'))
issues=[];warnings=[];file_evidence=[];path_count=0;empty_count=0
for p in files:
    raw=p.read_bytes();file_evidence.append({'file':p.name,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()})
    info=meta.get(p.stem,{})
    try:tree=ET.fromstring(raw)
    except ET.ParseError as exc:
        issues.append({'file':p.name,'motif':info.get('motif'),'displayName':info.get('displayName'),'errors':[{'type':'invalid_xml','detail':str(exc)}]});continue
    for index,node in enumerate(n for n in tree.iter() if n.tag.split('}')[-1]=='path'):
        d=node.attrib.get('d','')
        if not d.strip():empty_count+=1;continue
        path_count+=1
        errs,warns=validate(d)
        identity={'file':p.name,'pathIndex':index,'motif':info.get('motif'),'displayName':info.get('displayName'),'d':d}
        if errs:issues.append({**identity,'errors':errs})
        if warns:warnings.append({**identity,'warnings':warns})
grouped=collections.defaultdict(lambda:{'badPathCount':0,'files':set(),'errorTypes':collections.Counter(),'examples':[]})
for issue in issues:
    g=grouped[issue.get('motif','unknown')];g['badPathCount']+=1;g['files'].add(issue['file'])
    for err in issue['errors']:g['errorTypes'][err['type']]+=1
    if len(g['examples'])<3:g['examples'].append(issue)
patterns={motif:{**g,'files':sorted(g['files']),'fileCount':len(g['files']),'errorTypes':dict(g['errorTypes'])} for motif,g in grouped.items()}
receipt={'status':'failed' if issues else 'passed','scope':'Read-only SVG path syntax audit; does not prove visual correctness or identity. No assets modified.',
'auditedAtUnix':time.time(),'files':len(files),'nonemptyPaths':path_count,'emptyPaths':empty_count,'invalidPaths':len(issues),
'affectedFiles':len({i['file'] for i in issues}),'warningPaths':len(warnings),'parserSelfChecks':len(self_cases),
'commandCoverage':list(arity),'checks':['initial moveto','M/L/H/V/C/S/Q/T/A/Z arity and implicit repeats','SVG numeric lexing including exponent and signed adjacency','finite numbers','arc flags/radii','comma syntax','decimal adjacency warning','suspicious large coordinate warning'],
'patterns':patterns,'issues':issues,'warnings':warnings,'fileEvidence':file_evidence,'auditPython':globals().get('AUDIT_SOURCE','')}
out.write_text(json.dumps(receipt,ensure_ascii=False,indent=2))
print(json.dumps({k:receipt[k] for k in ['status','files','nonemptyPaths','invalidPaths','affectedFiles','warningPaths','parserSelfChecks']},ensure_ascii=False))
for motif,g in patterns.items():print(motif,g['fileCount'],g['badPathCount'],g['errorTypes'],g['examples'][0]['d'][:160])
